package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

var _ = decimal.NewFromInt

type PartRec struct {
	LbPart   string
	LbRegion string
	LbSerial int64
}

var WsEofFlag string = "N"
var WsLabel string = "                    "
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var partRec PartRec

var partFileLines []string
var partFileIndex int
var inputDone bool

func formatPIC9(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if s[0] == '-' {
		// Not expected but handle truncation/padding
		abs := s[1:]
		if len(abs) > digits {
			abs = abs[len(abs)-digits:]
		} else if len(abs) < digits {
			abs = strings.Repeat("0", digits-len(abs)) + abs
		}
		return "-" + abs // not needed for this program
	}
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func formatPIC99(v int64) string {
	return formatPIC9(v, 2)
}
func formatPIC999(v int64) string {
	return formatPIC9(v, 3)
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func main() {
	// OPEN INPUT PART-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	// Read all lines preserving content except newline
	// Use manual read to preserve trailing spaces
	scanner := bufio.NewScanner(f)
	// increase buffer for long lines
	const maxCap = 10 * 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)
	// bufio.Scanner strips \r and \n
	for scanner.Scan() {
		line := scanner.Text()
		// Remove trailing \r if file has CRLF (Scanner already handles \r\n but keep safe)
		// Scanner with default SplitScanLines already strips \r for \r\n
		partFileLines = append(partFileLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	// Handle case where file ends without newline vs empty file - same

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE PART-FILE - deferred
	SUMMARY_PARA()
}

func READ_PARA() {
	if partFileIndex >= len(partFileLines) {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	raw := partFileLines[partFileIndex]
	partFileIndex++
	// LINE SEQUENTIAL: pad with spaces on right to record length 15
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	partRec.LbPart = raw[0:8]
	partRec.LbRegion = raw[8:11]
	serialStr := raw[11:15]
	// PIC 9(4) - digits only; if spaces treat as 0? parse digits, ignoring spaces?
	serialStr = strings.TrimSpace(serialStr)
	if serialStr == "" {
		partRec.LbSerial = 0
	} else {
		var v int64
		fmt.Sscan(serialStr, &v)
		// Ensure only low-order digits kept is handled by parse, but serial in file is 4 digits
		partRec.LbSerial = v
	}
	WsEofFlag = "N"
	inputDone = false
}

func PROCESS_PARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount = int64(strings.Count(partRec.LbPart, "A"))

	// STRING ...
	// Build WS-LABEL buffer
	buf := make([]byte, 20)
	for i := range buf {
		buf[i] = ' '
	}
	pos := 0
	// helper to get delimited chunk
	delimitedBySpace := func(s string) string {
		if idx := strings.IndexByte(s, ' '); idx >= 0 {
			return s[:idx]
		}
		return s
	}
	// LB-REGION DELIMITED BY SPACE
	chunk := delimitedBySpace(partRec.LbRegion)
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	// "-" DELIMITED BY SIZE
	chunk = "-"
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	// LB-PART DELIMITED BY SPACE
	chunk = delimitedBySpace(partRec.LbPart)
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	// "-" DELIMITED BY SIZE
	chunk = "-"
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	// LB-SERIAL DELIMITED BY SIZE - formatted as 4-digit zero-padded
	chunk = formatPIC9(partRec.LbSerial, 4)
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	WsLabel = string(buf)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA += WsACount
	// ADD 1 TO WS-COUNT
	WsCount += 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) - print as is (20 chars)
	// WS-A-COUNT PIC 99 zero-padded 2 digits
	fmt.Printf("%s A=%s\n", WsLabel, formatPIC99(WsACount))

	READ_PARA()
}

func SUMMARY_PARA() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A.
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", formatPIC999(WsCount), formatPIC999(WsTotalA))
}

