package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

var _ = decimal.NewFromInt

type PartRec struct {
	LbPart   string
	LbRegion string
	LbSerial int64
	// raw 4-char serial as stored for STRING ... DELIMITED BY SIZE (digits only, no conversion)
	LbSerialRaw string
}

var WsEofFlag string = "N"
var WsLabel string = "                    "
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var partRec PartRec

var partFileLines []string
var partFileIndex int
var inputDone bool

func formatPIC9(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if s[0] == '-' {
		abs := s[1:]
		if len(abs) > digits {
			abs = abs[len(abs)-digits:]
		} else if len(abs) < digits {
			abs = strings.Repeat("0", digits-len(abs)) + abs
		}
		return "-" + abs
	}
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func formatPIC99(v int64) string {
	return formatPIC9(v, 2)
}
func formatPIC999(v int64) string {
	return formatPIC9(v, 3)
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	const maxCap = 10 * 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)
	for scanner.Scan() {
		line := scanner.Text()
		partFileLines = append(partFileLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}

func READ_PARA() {
	if partFileIndex >= len(partFileLines) {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	raw := partFileLines[partFileIndex]
	partFileIndex++
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	partRec.LbPart = raw[0:8]
	partRec.LbRegion = raw[8:11]
	serialStr := raw[11:15]
	partRec.LbSerialRaw = serialStr
	trimmed := strings.TrimSpace(serialStr)
	if trimmed == "" {
		partRec.LbSerial = 0
	} else {
		// Must parse as decimal base 10; fmt.Sscan would treat leading 0 as octal
		v, err := strconv.ParseInt(trimmed, 10, 64)
		if err != nil {
			// fallback: extract digits
			var d string
			for _, ch := range trimmed {
				if ch >= '0' && ch <= '9' {
					d += string(ch)
				}
			}
			if d != "" {
				v, _ = strconv.ParseInt(d, 10, 64)
			}
		}
		partRec.LbSerial = v
	}
	WsEofFlag = "N"
	inputDone = false
}

func PROCESS_PARA() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsACount = int64(strings.Count(partRec.LbPart, "A"))

	buf := make([]byte, 20)
	for i := range buf {
		buf[i] = ' '
	}
	pos := 0
	delimitedBySpace := func(s string) string {
		if idx := strings.IndexByte(s, ' '); idx >= 0 {
			return s[:idx]
		}
		return s
	}
	chunk := delimitedBySpace(partRec.LbRegion)
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	chunk = "-"
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	chunk = delimitedBySpace(partRec.LbPart)
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	chunk = "-"
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	// LB-SERIAL DELIMITED BY SIZE: PIC 9(4) stored as 4 digits, no decimal point
	// Use raw 4-char field as it appears in file (already exactly 4 bytes)
	chunk = partRec.LbSerialRaw
	// If input had short line padded, raw may contain spaces; COBOL would have moved numeric DISPLAY
	// field which is zero-padded; but our raw preserves file content which is correct for LINE SEQUENTIAL.
	// Ensure length 4: if raw contained fewer due to truncation, it's already padded to 15.
	for i := 0; i < len(chunk) && pos < 20; i++ {
		buf[pos] = chunk[i]
		pos++
	}
	WsLabel = string(buf)

	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA += WsACount
	WsCount += 1

	fmt.Printf("%s A=%s\n", WsLabel, formatPIC99(WsACount))

	READ_PARA()
}

func SUMMARY_PARA() {
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", formatPIC999(WsCount), formatPIC999(WsTotalA))
}
